package com.wipro.spring; import org.springframework.context.support.ClassPathXmlApplicationContext; public class Main{public static void main(String[]a){try(ClassPathXmlApplicationContext c=new ClassPathXmlApplicationContext("applicationContext.xml")){for(String id:new String[]{"p1","p2","p3","p4","p5"})c.getBean(id,Player.class).print();System.out.println("Players from India:");for(String id:new String[]{"p1","p2"})System.out.println(c.getBean(id,Player.class).getPlayerName());}}}